/**
 * Slash commands: definitions (registered by scripts/register-commands.mjs) and their handlers.
 * Usable only in the REPLY_CATEGORY_IDS categories (anywhere else gets a private refusal); who may use them is controlled in Discord (Server Settings → Integrations).
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L19  Definitions
// L24    COMMANDS
// L39  Handlers
// L44    onInteraction()
// L58    handleMesonQuery()
// ----- end of contents -----

import { MessageFlags, SlashCommandBuilder } from 'discord.js'
import { lookupSwap, SwapNotFound } from './meson.js'
import { extractCandidates } from './extract.js'
import { buildSwapEmbed, buildNotFoundEmbed, QUERY_WRONG_CHANNEL_MESSAGE } from './render.js'
import { inReplyCategory } from './discord-util.js'

// =============================================================================
//   Definitions
// =============================================================================

/** Command definitions, as sent to Discord by `npm run register`. */
export const COMMANDS = [
  new SlashCommandBuilder()
    .setName('meson-query')
    .setDescription('Look up one Meson swap')
    .addStringOption((o) =>
      o.setName('swap')
        .setDescription('Swap ID, source or destination tx hash, or an explorer link (Meson or the chain\'s)')
        .setRequired(true))
    .addBooleanOption((o) =>
      o.setName('private')
        .setDescription('Only show the result to you (default: visible to the ticket)')
        .setRequired(false))
    .toJSON(),
]

// =============================================================================
//   Handlers
// =============================================================================

/** InteractionCreate entry point. A failed reply (e.g. Discord's 3-second window missed: "Unknown interaction") is logged, never thrown. */
export async function onInteraction (interaction) {
  if (!interaction.isChatInputCommand()) return
  try {
    if (interaction.commandName === 'meson-query') await handleMesonQuery(interaction)
  } catch (err) {
    console.error(`/${interaction.commandName}: could not reply —`, err.message)
  }
}

/**
 * /meson-query: posts the same details embed a ticket gets. Tries the candidates in priority order and shows the first that resolves.
 *
 *   /meson-query swap:<swap ID | tx hash | explorer link> [private]
 */
async function handleMesonQuery (interaction) {
  if (!inReplyCategory(interaction.channel)) {
    await interaction.reply({ content: QUERY_WRONG_CHANNEL_MESSAGE, flags: MessageFlags.Ephemeral })
    return
  }
  const query = interaction.options.getString('swap', true)
  const isPrivate = interaction.options.getBoolean('private') ?? false
  await interaction.deferReply(isPrivate ? { flags: MessageFlags.Ephemeral } : {})

  const candidates = extractCandidates(query)
  if (!candidates.length) {
    await interaction.editReply({
      embeds: [buildNotFoundEmbed(null, { hint: 'That does not look like a swap ID, a transaction hash or an explorer link.' })],
    })
    return
  }

  try {
    for (const query of candidates) {
      try {
        const swap = await lookupSwap(query)
        await interaction.editReply({ embeds: [buildSwapEmbed(swap, { requestedBy: interaction.user.username })] })
        return
      } catch (err) {
        if (!(err instanceof SwapNotFound)) throw err
      }
    }
    await interaction.editReply({ embeds: [buildNotFoundEmbed(candidates[0])] })
  } catch (err) {
    console.error('/meson-query failed —', err)
    await interaction.editReply({
      embeds: [buildNotFoundEmbed(null, { hint: 'The Meson explorer did not respond. Please try again in a moment.' })],
    })
  }
}
